// @vitest-environment happy-dom
// Earth named search and name labels on the approved list (registry/earth/places.yaml, generated by
// scripts/places/build_earth_places.py): matches across both lines, aliases (diacritics ignored), sub-units
// and countries; the labels' second lines in their scripts (RTL, CJK, Cyrillic; Devanagari in the popup
// only); Indigenous names of Great Sand Dunes; no review columns shipped; the size of the place file;
// the naming note under the search results, beside 'Show names' and in About.
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { describe, expect, it, vi } from "vitest";
import { loadPlaces, matchPlaces, nameVariantKey, otherNames, placesNoteHtml, type Place } from "../src/core/search/places";
import { labelRadius, placeFeatures, placePopupContent, placesNeedRtl } from "../src/core/map/placelabels";
import { SearchBox } from "../src/core/ui/search";
import { DATA_SOURCES_HTML, renderLayerPanel } from "../src/core/ui/layerPanel";
import { loadRegistry } from "../src/core/registry/load";
import { initialAppState } from "../src/core/defaultview";
import { Store } from "../src/core/store";
import { PROFILE } from "../src/bodies/earth/profile";

const FILE = path.resolve(__dirname, "../../registry/earth/places.yaml");
const LIST = loadPlaces();
const P = LIST.places;
const byId = (id: string) => P.find((p) => p.id === id)!;
const top = (q: string) => matchPlaces(q, P)[0];

describe("Earth place list", () => {
  it("enabled, every approved row, names verbatim; no review columns", () => {
    expect(LIST.enabled).toBe(true);
    expect(P).toHaveLength(303);
    expect(byId("rub-al-khali-empty-quarter").line1).toBe("Rub' al Khali");
    const text = fs.readFileSync(FILE, "utf8");
    for (const col of ["confidence", "sensitivity", "pi_decision", "pi_note", "scores_source", "label_priority", "local_recognition", "aeolian_recognition", "single_dune", "verified", "reference_notes", "change_from_draft", "line2_reason"])
      expect(text, col).not.toContain(col);
    expect(text).not.toMatch(/scanned paper in/);   // an internal holding note of one reference
    for (const p of P) {
      expect(p.sources.length, p.id).toBeGreaterThan(0);
      expect(p.countries?.length, p.id).toBeGreaterThan(0);
      expect(p.dune_km2, p.id).toBeGreaterThan(0);
      expect(Math.abs(p.lon), p.id).toBeLessThanOrEqual(180);
    }
  });
  it("place file size: within the bundle budget (loaded with the app; gzip on the wire)", () => {
    const raw = fs.statSync(FILE).size, gz = zlib.gzipSync(fs.readFileSync(FILE)).length;
    expect(raw).toBeLessThan(160_000);
    expect(gz).toBeLessThan(40_000);
  });
  it("line 2 with its language: Arabic, Pashto, Chinese, Uzbek and Ukrainian Cyrillic, Hindi", () => {
    expect(byId("rub-al-khali-empty-quarter").line2).toEqual({ text: "الربع الخالي", lang: "ar" });
    expect(byId("taklamakan-desert").line2).toEqual({ text: "塔克拉玛干沙漠", lang: "zh-Hans" });
    expect(byId("registan-desert").line2).toEqual({ text: "ریگستان", lang: "ps" });
    expect(byId("kyzylkum-desert").line2).toEqual({ text: "Қизилқум", lang: "uz-Cyrl" });
    expect(byId("oleshky-sands").line2).toEqual({ text: "Олешківські піски", lang: "uk" });
    expect(byId("thar-desert").line2).toEqual({ text: "थार मरुस्थल", lang: "hi" });
    expect(P.filter((p) => p.line2)).toHaveLength(96);
  });
});

describe("Earth named search", () => {
  it("across both lines", () => {
    expect(top("Taklamakan").place.id).toBe("taklamakan-desert");
    expect(top("塔克拉玛干").place.id).toBe("taklamakan-desert");
    expect(top("الربع الخالي").place.id).toBe("rub-al-khali-empty-quarter");
    expect(top("Олешківські").place.id).toBe("oleshky-sands");
    expect(top("Rub al Khali").place.id).toBe("rub-al-khali-empty-quarter");
  });
  it("aliases and alternative names, diacritics and apostrophes ignored", () => {
    expect(top("Empty Quarter").place.id).toBe("rub-al-khali-empty-quarter");
    expect(top("Great Indian Desert")).toMatchObject({ place: { id: "thar-desert" }, kind: "alias" });
    expect(top("seinanyedi")).toMatchObject({ place: { id: "great-sand-dunes" }, kind: "alias", matched: "Seinanyédi" });
    expect(top("Tse-whiz-hosh").place.id).toBe("great-sand-dunes");
    expect(top("So-wop-a-wot").place.id).toBe("great-sand-dunes");
    expect(top("Saa waap maa nache").place.id).toBe("great-sand-dunes");
  });
  it("sub-units resolve to the parent", () => {
    expect(top("Cholistan")).toMatchObject({ place: { id: "thar-desert" }, kind: "alias", matched: "Cholistan Desert" });
    expect(top("صحرائے چولستان").place.id).toBe("thar-desert");
    expect(top("Liwa").place.id).toBe("rub-al-khali-empty-quarter");
    expect(top("Witsand").place.id).toBe("kalahari");
    expect(top("Big Desert").place.id).toBe("mallee-dune-field");
  });
  it("countries and territories: typed in full first, by mapped dune area; partly typed below the names", () => {
    const hits = matchPlaces("Namibia", P).filter((h) => h.kind === "country");
    expect(hits.length).toBeGreaterThan(1);
    expect(matchPlaces("Namibia", P)[0].kind).toBe("country");
    expect(hits.every((h) => h.place.countries!.includes("Namibia"))).toBe(true);
    const areas = hits.map((h) => h.place.dune_km2!);
    expect(areas).toEqual([...areas].sort((a, b) => b - a));
    expect(matchPlaces("Western Sahara", P).slice(0, 2).map((h) => [h.kind, h.matched])).toEqual([["country", "Western Sahara"], ["country", "Western Sahara"]]);   // as in the table
    expect(matchPlaces("Mauritan", P).filter((h) => h.kind === "country").every((h) => h.score === 40)).toBe(true);
    // a name beats a country: "Namib" finds the Namib Sand Sea by its name
    expect(top("Namib")).toMatchObject({ kind: "name" });
  });
  it("the results show the countries and the other name that matched; 'About these names' opens the note", () => {
    const b = new SearchBox({ ...PROFILE.search, places: LIST, namesNoteHtml: placesNoteHtml(LIST), goTo: vi.fn(async () => ""), goToPlace: (p: Place) => p.line1 });
    document.body.replaceChildren(b.el);
    b.input.value = "Cholistan"; b.input.dispatchEvent(new Event("input"));
    const li = b.list.querySelector("li")!;
    expect(li.querySelector(".hit-line1")!.textContent).toBe("Thar Desert");
    expect(li.querySelector(".hit-alias")!.textContent).toBe("Cholistan Desert");
    expect(li.querySelector(".hit-country")!.textContent).toBe("India, Pakistan");
    expect(b.namesFoot.hidden).toBe(false);
    const link = b.namesFoot.querySelector("button")!;
    expect(link.textContent).toBe("About these names");
    expect(b.namesNote.hidden).toBe(true);
    link.click();
    expect(b.namesNote.hidden).toBe(false);
    expect(link.getAttribute("aria-expanded")).toBe("true");
    expect(b.namesNote.innerHTML).toBe(placesNoteHtml(LIST));
    expect(b.namesNote.querySelector("a")!.getAttribute("href")).toBe("mailto:a.gunn@monash.edu");
    b.input.value = ""; b.input.dispatchEvent(new Event("input"));
    expect(b.namesFoot.hidden).toBe(true);
    expect(b.namesNote.hidden).toBe(true);
  });
});

describe("Earth name labels", () => {
  const fc = placeFeatures(LIST);
  const f = (id: string) => fc.features.find((x) => x.properties!.id === id)!.properties!;
  it("second lines on the map: Arabic-script (RTL plugin), CJK, Cyrillic; Devanagari in the popup only", () => {
    expect(f("rub-al-khali-empty-quarter").line2).toBe("الربع الخالي");
    expect(f("registan-desert").line2).toBe("ریگستان");
    expect(f("taklamakan-desert").line2).toBe("塔克拉玛干沙漠");
    expect(f("kyzylkum-desert").line2).toBe("Қизилқум");
    expect(f("oleshky-sands").line2).toBe("Олешківські піски");
    expect(f("thar-desert").line2).toBeUndefined();
    expect(placePopupContent(byId("thar-desert")).querySelector(".place-line2")!.textContent).toBe("थार मरुस्थल");
    expect(placesNeedRtl(LIST)).toBe(true);
  });
  it("big ergs win collisions: priority by radius and mapped dune area; every name at every zoom, one size", () => {
    const sorted = [...P].sort((a, b) => labelRadius(b) - labelRadius(a));
    expect(sorted.slice(0, 3).map((p) => p.id)).toEqual(["rub-al-khali-empty-quarter", "kalahari", "taklamakan-desert"]);
    expect(f("rub-al-khali-empty-quarter").rank).toBeLessThan(f("great-sand-dunes").rank);
    for (const p of P) { expect(f(p.id).minzoom, p.id).toBe(0); expect(f(p.id).size, p.id).toBe(f("great-sand-dunes").size); }
  });
  it("Great Sand Dunes popup: the Indigenous names with their languages", () => {
    const el = placePopupContent(byId("great-sand-dunes"));
    const t = el.textContent!;
    for (const s of ["So-wop-a-wot", "Ute", "Seinanyédi", "Jicarilla Apache", "Tsé-whíz-hosh", "Navajo (Diné)"]) expect(t, s).toContain(s);
    expect(el.querySelectorAll(".place-alt li")).toHaveLength(4);
    expect(t).toContain("United States");
  });
  it("sub-units in the popup ('Includes')", () => {
    expect(placePopupContent(byId("kalahari")).textContent).toContain("Includes: Northeastern Kalahari Dune Field, Northwestern Kalahari Dune Field");
    expect(placePopupContent(byId("thar-desert")).textContent).toContain("Includes: Cholistan Desert (صحرائے چولستان)");
  });
  it("'Show names' in the Dunes group with the naming note beside it; the note in About", () => {
    const reg = loadRegistry().registry;
    document.body.innerHTML = '<aside id="layer-panel"></aside>';
    renderLayerPanel(document.getElementById("layer-panel")!, reg, new Store(initialAppState(reg, {}, "era5")));
    const row = document.getElementById("show-names")!.closest(".names-row")!;
    expect(row.closest("details.layer-group")!.querySelector("summary")!.textContent).toBe("Dunes");
    expect(row.querySelector(".info-popover")!.innerHTML).toContain(placesNoteHtml(LIST));
    expect(DATA_SOURCES_HTML).toContain(`<strong>Dune-field names</strong>: ${placesNoteHtml(LIST)}`);
  });
});

describe("Earth other names: substantive differences only", () => {
  it("spelling-only variants of the name are not shown as 'Also called' (search still finds them)", () => {
    expect(nameVariantKey("Alexandria coastal dunefield")).toBe(nameVariantKey("Alexandria Coastal Dune Field"));
    expect(nameVariantKey("Nebraska Sandhills")).toBe(nameVariantKey("Nebraska Sand Hills"));
    expect(nameVariantKey("Rig-e-Yalan")).toBe(nameVariantKey("Rig-e Yalan"));
    expect(nameVariantKey("Empty Quarter")).not.toBe(nameVariantKey("Rub' al Khali"));
    const p = LIST.places.find((x) => x.id === "alexandria-coastal-dunefield")!;
    expect(otherNames(p)).toEqual([]);
    expect(placePopupContent(p).textContent).not.toContain("Also called");
    const hit = matchPlaces("alexandria coastal dunefield", LIST.places)[0];
    expect(hit).toMatchObject({ kind: "name", matched: "Alexandria Coastal Dune Field" });
    const rub = LIST.places.find((x) => x.line1 === "Rub' al Khali")!;
    expect(otherNames(rub).map((a) => a.text)).toContain("Empty Quarter");
  });
  it("no place shows a variant of its own name or the same name twice", () => {
    for (const p of LIST.places) {
      const keys = otherNames(p).map((a) => nameVariantKey(a.text));
      expect(keys, p.id).not.toContain(nameVariantKey(p.line1));
      expect(new Set(keys).size, p.id).toBe(keys.length);
    }
  });
});
